package com.plumemu.identify.source

import java.io.Closeable
import java.io.IOException

/**
 * Bytes that can be read at any position without reading what comes before: a ROM file, an
 * archive, later a decompressed disc image. Every reader in this module works on this, so a test
 * can hand it generated bytes and a measurement can count what was read ([CountingSource]).
 *
 * Implementations must allow concurrent [readAt] calls from several threads (positional reads
 * keep no cursor), and may return fewer bytes than asked.
 */
interface RandomAccessSource : Closeable {
    /** Total length in bytes. */
    val size: Long

    /**
     * Reads up to [length] bytes starting at [position] into [dst] at [offset].
     *
     * @return the number of bytes read, possibly fewer than [length]; -1 when [position] is at or
     *   past the end.
     * @throws IOException when the underlying storage fails.
     */
    @Throws(IOException::class)
    fun readAt(position: Long, dst: ByteArray, offset: Int, length: Int): Int
}

/**
 * Reads [length] bytes at [position], clamped to the end of the source: near the end the array
 * is shorter, past the end it is empty. Loops over short reads.
 *
 * @throws IOException when the underlying storage fails.
 */
@Throws(IOException::class)
fun RandomAccessSource.readFully(position: Long, length: Int): ByteArray {
    require(position >= 0 && length >= 0) { "negative position or length" }
    val available = (size - position).coerceAtLeast(0)
    val wanted = minOf(length.toLong(), available).toInt()
    val out = ByteArray(wanted)
    val got = readInto(position, out, wanted)
    return if (got == wanted) out else out.copyOf(got)
}

/** Fills [dst] from index 0 with up to [length] bytes at [position]; returns how many were read. */
@Throws(IOException::class)
internal fun RandomAccessSource.readInto(position: Long, dst: ByteArray, length: Int): Int {
    var done = 0
    while (done < length) {
        val n = readAt(position + done, dst, done, length - done)
        if (n < 0) break
        if (n == 0) {
            // A source that answers 0 forever would loop here; treat it like the end.
            break
        }
        done += n
    }
    return done
}

/**
 * Opens a file named by another one: the tracks a `.cue` or `.gdi` lists, the discs of an
 * `.m3u`. [fileName] is the name as written in the referring file, relative to its folder.
 * Returns null when there is no such file. Used by the disc readers.
 */
fun interface SiblingOpener {
    @Throws(IOException::class)
    fun open(fileName: String): RandomAccessSource?
}
